import { defineConfig, devices } from '@playwright/test';

// Runs against the production build (`yarn build` first), because the site's own CSP
// <meta> policy is only generated by `astro build`. Any CSP violation fails the tests.
export default defineConfig({
  testDir: 'tests/e2e',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  use: {
    baseURL: 'http://localhost:4321',
    permissions: ['clipboard-read', 'clipboard-write'],
  },
  projects: [
    { name: 'desktop', use: { ...devices['Desktop Chrome'] } },
    { name: 'mobile', use: { ...devices['Pixel 7'] } },
  ],
  webServer: {
    // --ignore-lock keeps the server in the foreground (Astro otherwise backgrounds it when run by a coding agent).
    command: 'yarn astro preview --port 4321 --ignore-lock',
    url: 'http://localhost:4321',
    reuseExistingServer: !process.env.CI,
  },
});
